<script setup>
import { ref, reactive, computed, watch, onMounted, onBeforeUnmount, shallowRef } from 'vue';
import { ArrowRight, ArrowUpRight, Plus, Flashlight, Map, BookOpen, Crosshair, Volume2, VolumeX, Settings2, X, Check, ChevronRight, Shield, Footprints, Wind, CircleHelp, Pause, RotateCcw, Radio, AlertTriangle, Coins, Power, Maximize, UserRound, DoorOpen, Clock, Eye, Target, HeartPulse, Headphones, Smartphone } from 'lucide-vue-next';
import {TimerScope} from './game/lifetime.js';
import { GameEngine } from './game/engine.js';
import { Mission, readSave, writeSave, purchase, UPGRADE_INFO } from './game/mission.js';
import { portrait } from './game/assets.js';
import TouchControls from './mobile/TouchControls.vue';
import { startCameraDiagnostics } from './mobile/camera-diagnostics.js';
import { installGameGestureGuard } from './mobile/gesture-guard.js';
import {native,platform,touchDevice,initializeNative,nativeFeedback} from './mobile/platform.js';
import { App as NativeApp } from '@capacitor/app';
import './mobile/mobile.css';
import MapView from './MapView.vue';
import StoryIntro from './StoryIntro.vue';
import CharacterStudio from './CharacterStudio.vue';
import {FLOORS,FLOOR_CODES,FLOOR_THEMES} from './game/layout.js';
import {CHARACTERS,defaultAppearance,profileFor,selectCharacter,weaponInfo} from './game/loadout.js';
import {STORY_SOURCES,STORY_NOTICE} from './game/stories.js';
import {prepareAssignment,markIntroSeen,selectAssignmentType} from './game/assignment.js';
import {assignmentType,TYPE_LABELS,ASSIGNMENT_TYPES} from './game/assignment-types.js';
import './missions-v4.css';
import './revision-2.4.css';
import './revision-2.5.css';
import {evidenceEnding} from './game/evidence-ending.js';
import {RECRUIT_DIALOGUE} from './game/life-rules.js';
import './hospital-v3.css';
import {assetUrl} from './game/asset-url.js';
import './expansion.css';
import './revision-2.7.css';
import {HOSPITAL_NAME} from './game/branding.js';
import {MenuMusic} from './game/menu-music.js';
const viewport = ref(null), screen = ref('menu'), overlay = ref(null), ready = ref(false), loading = ref(false), error = ref(null), locked = ref(false);
const isTouch=ref(touchDevice());let nativeCleanup=()=>{};
let removeGestureGuard=()=>{};
let stopCameraDiagnostics=()=>{};
let engine,appDisposed=false,debugBridge,diagnosticGetter;const feedbackTimers=new TimerScope();
const save = reactive(readSave(localStorage));if(isTouch.value&&!localStorage.getItem('ktd-northline-v1'))save.settings.quality='balanced';
const menuMusic=new MenuMusic(save.settings);const menuSound=ref(false);
function enableMenuSound(){menuMusic.unlock();menuSound.value=!!menuMusic.ctx;}
function menuGesture(){if(screen.value==='menu')enableMenuSound();}
function menuVisibility(){menuMusic.sync();}
watch(screen,value=>menuMusic.setActive(value==='menu'));
const hud = reactive({ state: 'investigate', location: 'Main atrium', floor: 0, x: 3, z: 30, yaw: Math.PI, timer: 0, stamina: 100, suspicion: 0, flashlight: false, blackout: 0, impairment: 0, aiming: false, ammo: 6, reserve: 30, prompt: null, clues: 0 });
const mission = shallowRef(null), result = ref(null), toast = ref(null), announcement = ref(null), clue = ref(null), badge = ref(null), mapFloor = ref(0), shotFlash = ref(false), transition = ref(false), hit = ref(false), soundCaption = ref(null);
const assignmentPortrait = ref(null);
const characterPortraits = reactive({ male: null, female: null,custom:null });
const contactDialog=ref(null);
const contactLines=computed(()=>{const d=contactDialog.value;if(!d)return [];if(d.stage==='invite')return [{speaker:d.name,text:RECRUIT_DIALOGUE.invite}];if(d.stage==='offer')return [{speaker:d.name,text:RECRUIT_DIALOGUE.question},{speaker:character.value,text:RECRUIT_DIALOGUE.offer,player:true}];return [{speaker:d.name,text:RECRUIT_DIALOGUE.accept}];});
function playContactLine(){const line=contactLines.value[contactDialog.value?.index||0];if(line)engine?.incidents?.speakRecruit(line.text,line.player?'player':'contact');}
function openContact(data){contactDialog.value={...data,index:0};openOverlay('contact');engine.audio.pause(false);playContactLine();}
function nextContactLine(){contactDialog.value.index++;playContactLine();}
function contactChoice(choice){if(!engine.incidents.choose(choice)){notification({text:'Find an empty room and stay close to your contact.',kind:'info'});return;}if(choice==='recruit'){contactDialog.value.stage='accepted';contactDialog.value.index=0;playContactLine();}else{engine.incidents.speakRecruit(choice==='escort'?RECRUIT_DIALOGUE.escort:RECRUIT_DIALOGUE.dismiss,'player');closeOverlay();}}
function syncCharacterPortraits(){if(!engine?.ready)return;for(const c of CHARACTERS){const appearance=c.id==='custom'?save.character==='custom'?save.appearance:save.customAppearance:defaultAppearance(c);characterPortraits[c.id]=engine.portrait(profileFor({character:c.id,appearance}),'civilian');}}
const character=computed(()=>profileFor(save).name);const activeStory=ref(null);
const nextAssignment=computed(()=>assignmentType(save));
function chooseAssignment(type){const switching=screen.value==='game';if(!ASSIGNMENT_TYPES.includes(type))return;if(switching){mission.value?.finish(false,'A different assignment was selected.');engine?.stop();}selectAssignmentType(save,type);prepareAssignment(save);persist();overlay.value=null;if(switching)startMission();}
const selectedProfile=computed(()=>profileFor(save));
function chooseCharacter(id){selectCharacter(save,id);persist();}
function loadoutChanged(){persist();engine?.refreshLoadout();}
function activatePrompt(event){if(event.type==='click'&&event.detail!==0||event.type==='pointerup'&&event.button!==0)return;engine?.interact();}
function useLift(floor){engine.travelToFloor(floor);closeOverlay();}
const countdown = computed(() => `${Math.floor(hud.timer/60).toString().padStart(2,'0')}:${Math.ceil(hud.timer%60).toString().padStart(2,'0')}`);
const duration = s => `${Math.floor(s/60)}:${Math.floor(s%60).toString().padStart(2,'0')}`;
const objectiveNumber = computed(() => hud.state === 'escape' ? '03' : hud.targetConfirmed ? '02' : '01');
const persist = () => writeSave(localStorage, save);
function notification(value) { toast.value = value; feedbackTimers.after('toast',5500,()=>toast.value=null); }
function openOverlay(name) { overlay.value = name; engine?.pause(true); if (name === 'map') mapFloor.value = hud.floor; }
function closeOverlay() { if(overlay.value==='characters')syncCharacterPortraits();overlay.value = null; clue.value = null; badge.value = null; if (screen.value === 'game') engine?.pause(false); else if(['story','ending'].includes(screen.value)) engine?.audio.pause(false); }
function pause() { if (screen.value !== 'game' || loading.value) return; if (overlay.value) closeOverlay(); else openOverlay('pause'); }
function startMission(){
  if(loading.value||screen.value==='story')return;
  const assignment=prepareAssignment(save);activeStory.value=assignment.story;persist();
  if(assignment.introSeen){enterHospital();return;}
  engine?.stop();engine.storyMusic=true;engine?.audio.start();overlay.value=null;screen.value='story';
}
function restartMission(){if(loading.value)return;mission.value?.finish(false,'Assignment restarted.');persist();enterHospital();}
async function enterHospital() {
  if (loading.value||!engine||appDisposed) return;
  feedbackTimers.clear();shotFlash.value=false;hit.value=false;transition.value=false;soundCaption.value=null;
  engine.storyMusic=false;engine?.audio.start();loading.value = true; error.value = null;
  try {
    const assignment=prepareAssignment(save);markIntroSeen(save);persist();mission.value = new Mission(save,assignment.seed,assignment.attempt); result.value = null; overlay.value = null; toast.value = null; announcement.value = null; screen.value = 'game';
    const currentEngine=engine;const started=await currentEngine.start(mission.value, save.character);if(appDisposed||currentEngine!==engine||!started)return;assignmentPortrait.value = currentEngine.portrait(mission.value.target, mission.value.target.name.startsWith('Nurse') ? 'nurse' : 'doctor'); ready.value = true;
    if(currentEngine.paused&&!overlay.value)openOverlay('pause');
    notification({ text: mission.value.type==='evidence'?'Evidence only · find the keys, photograph three subjects, and leave without killing anyone':mission.value.type==='rescue'?'Rescue operation · find both keys and reach the basement theatre':isTouch.value?'Move with the stick, drag to look, and tap USE at the staff directory.':'Start at the staff directory. Press E to inspect it.', kind: 'info' });
  } catch (e) { if(!appDisposed){error.value = `The game could not start: ${e.message}`; screen.value = 'menu';} }
  finally{if(!appDisposed)loading.value=false;}
}
function showResults(){engine.storyMusic=false;engine.audio.pause(true);screen.value='results';}
function missionResult(value){nativeFeedback(value.success?'success':'warning');result.value=value;overlay.value=null;persist();if(value.success&&value.type==='evidence'){const profile=engine.playerProfile||profileFor(save);engine.stop();activeStory.value=evidenceEnding(profile,value.coins);screen.value='ending';engine.storyMusic=true;engine.audio.start();}else screen.value='results';}
function toMenu() { feedbackTimers.clear();shotFlash.value=false;hit.value=false;transition.value=false;soundCaption.value=null;if(engine)engine.storyMusic=false;engine?.stop(); screen.value = 'menu'; overlay.value = null; announcement.value = null; toast.value = null; persist(); }
function buy(id) { if (purchase(save, id)) { persist();engine?.refreshLoadout(); engine?.audio.sound('clue'); } }
function settingsChanged() { menuMusic.sync();persist(); engine?.applySettings(save.settings); }
function toggleSound() { save.settings.volume = save.settings.volume ? 0 : .5; settingsChanged(); }
function fullscreen() { if(native)return; if (!document.fullscreenElement) document.documentElement.requestFullscreen?.().catch(()=>{}); else document.exitFullscreen?.(); }
function globalKey(e) {
  if (overlay.value === 'map' && (e.code === 'KeyM' || e.code === 'Tab')) { e.preventDefault(); closeOverlay(); }
  else if (overlay.value === 'journal' && e.code === 'KeyJ') closeOverlay();
  else if (screen.value !== 'game' && e.code === 'Escape' && overlay.value) closeOverlay();
}
onMounted(() => {
  try {
    engine = new GameEngine(viewport.value, save.settings, {
      error:value=>{error.value=`Character assets could not load: ${value.message}`;},
      ready:()=>{ready.value=true;syncCharacterPortraits();},
      contact:openContact,
      hud: state => Object.assign(hud, state),
      pause,persist, lift:()=>openOverlay('lift'), map: () => openOverlay('map'), journal: () => openOverlay('journal'), lock: value => locked.value = value,
      notify: notification,
      announcement: value => { announcement.value = value; feedbackTimers.after('announcement',11000,()=>announcement.value=null); },
      soundCaption: text => { soundCaption.value=text; feedbackTimers.after('caption',6500,()=>soundCaption.value=null); },
      clue: value => { nativeFeedback(); clue.value = value; openOverlay('clue'); },
      badge: value => { badge.value = value; openOverlay('badge'); },
      shot: () => { nativeFeedback('shot');shotFlash.value = true; feedbackTimers.after('shot',95,()=>shotFlash.value=false); },
      hit: () => { hit.value = true; feedbackTimers.after('hit',260,()=>hit.value=false); },
      transition: () => { transition.value = true; feedbackTimers.after('transition',450,()=>transition.value=false); },
      result:missionResult,
    });
    // Dev-only inspection enables browser acceptance tests without changing the shipped UI.
    if (import.meta.env.DEV || import.meta.env.MODE==='native-test') window.__ktd = debugBridge = { get engine() { return engine; }, get mission() { return mission.value; }, get save() { return save; }, get hud() { return hud; } };
  } catch (e) { error.value = `WebGL could not initialize. Try a browser with hardware acceleration enabled. ${e.message}`; }
  initializeNative({background:()=>{persist();engine?.resetTouch();if(screen.value==='game'&&!overlay.value)openOverlay('pause');else engine?.pause(true);},back:()=>{if(overlay.value)closeOverlay();else if(screen.value==='game')pause();else if(screen.value==='results'||screen.value==='story'||screen.value==='ending')toMenu();else NativeApp.exitApp();}}).then(cleanup=>{if(appDisposed)cleanup();else nativeCleanup=cleanup;}).catch(()=>{});
  diagnosticGetter=()=>({platform,native,touch:isTouch.value,screen:screen.value,overlay:overlay.value,ready:ready.value,loading:loading.value,error:error.value,position:engine?.playerPos?.toArray(),yaw:engine?.yaw,paused:engine?.paused,frame:engine?.renderer.info.render.frame,fps:engine?.performance.fps,state:engine?.mission?.state,ammo:engine?.ammo,flashlight:engine?.flashlight,clues:engine?.mission?.clues.length,controls:{...engine?.touchInput},inputEvents:{...engine?.inputEvents},coins:save.coins,upgrades:{...save.upgrades},settings:{...save.settings},audio:{state:engine?.audio.ctx?.state,samples:Object.keys(engine?.audio.samples||{}),voices:engine?.audio.dialogueBuffers.size},url:location.href});
  Object.defineProperty(window,'__northline',{configurable:true,get:diagnosticGetter});
  if(import.meta.env.DEV)stopCameraDiagnostics=startCameraDiagnostics(()=>engine);
  window.addEventListener('keydown',globalKey);window.addEventListener('pointerdown',menuGesture,{passive:true});window.addEventListener('keydown',menuGesture);document.addEventListener('visibilitychange',menuVisibility);
  removeGestureGuard=installGameGestureGuard(document,()=>screen.value==='game'&&!overlay.value);
});
onBeforeUnmount(() => { appDisposed=true;menuMusic.dispose();window.removeEventListener('pointerdown',menuGesture);window.removeEventListener('keydown',menuGesture);document.removeEventListener('visibilitychange',menuVisibility);removeGestureGuard();stopCameraDiagnostics();nativeCleanup();feedbackTimers.dispose();engine?.dispose();engine=null;if(window.__ktd===debugBridge)delete window.__ktd;if(Object.getOwnPropertyDescriptor(window,'__northline')?.get===diagnosticGetter)delete window.__northline;window.removeEventListener('keydown',globalKey); });
</script>
<template>
  <main class="game-shell" :style="{ '--impairment-blur': `${(hud.impairmentStrength || 0)*3}px` }" :class="[{ 'mobile-mode':isTouch,'native-mode':native,'has-overlay':!!overlay, 'in-game': screen === 'game', 'impaired': hud.impairment > 0 && screen === 'game', 'blackout': hud.blackout > 0 && screen === 'game', 'emergency': hud.state === 'escape' && screen === 'game' }, screen]">
    <div v-if="isTouch" class="rotate-phone"><Smartphone :size="44"/><h2>Turn your phone.</h2><p>Nhalewick plays in landscape. Rotate your phone for the full game and touch controls.</p></div>
    <div ref="viewport" class="viewport" :class="{ 'shot': shotFlash }"></div>
    <div class="vignette" aria-hidden="true"></div><div class="grain" aria-hidden="true"></div>
    <div v-if="transition" class="floor-transition"></div>
    <template v-if="screen === 'menu'">
      <header class="menu-header"><a class="brand" href="#" @click.prevent="toMenu"><span class="brand-mark"><Plus :size="25" :stroke-width="1.3"/></span><span>{{HOSPITAL_NAME.toUpperCase()}}<small>MEDICAL CENTER</small></span></a><button class="menu-audio-button" @click="enableMenuSound" :aria-pressed="menuSound"><Headphones :size="14"/>{{menuSound?'MENU SOUND ON':'ENABLE MENU SOUND'}}</button><div class="header-status"><span class="live-dot"></span> ALL SYSTEMS OPERATIONAL <span class="header-time">02:14 AM</span></div></header>
      <section class="menu-content">
        <div class="menu-intro">
        <div class="eyebrow"><span class="line"></span> A THIRD-PERSON STEALTH THRILLER</div>
        <h1 aria-label="KTD — Kill the Doctor"><span class="ktd-wordmark" aria-hidden="true">KTD</span><span class="title-full">KILL THE DOCTOR</span></h1>
        <p class="tagline">Everyone has a reason to be here.<br/>Yours is different.</p>
        <div class="mission-premise"><span class="section-number">01 /</span><p>Enter Nhalewick. Follow the evidence. Find your assigned target. Then get out before the hospital locks down.</p></div>
        </div>
        <div class="menu-launch">
        <div class="character-select"><div class="field-label">{{selectedProfile.name.toUpperCase()}} <span>SELECT YOUR PROTAGONIST</span></div>
          <div class="character-options"><button :class="{selected: save.character === 'male'}" @click="chooseCharacter('male')" :aria-pressed="save.character === 'male'"><img v-if="characterPortraits.male" :src="characterPortraits.male" alt="Adrian portrait"/><UserRound v-else :size="24"/><span>ADRIAN<small>Male protagonist</small></span><Check v-if="save.character==='male'" :size="17"/></button><button :class="{selected: save.character === 'female'}" @click="chooseCharacter('female')" :aria-pressed="save.character === 'female'"><img v-if="characterPortraits.female" :src="characterPortraits.female" alt="Alex portrait"/><UserRound v-else :size="24"/><span>ALEX<small>Female protagonist</small></span><Check v-if="save.character==='female'" :size="17"/></button><button :class="{selected:save.character==='custom'}" @click="chooseCharacter('custom')" :aria-pressed="save.character==='custom'"><img v-if="characterPortraits.custom" :src="characterPortraits.custom" alt="Custom character portrait"/><UserRound v-else :size="24"/><span>CUSTOM<small>Your character</small></span><Check v-if="save.character==='custom'" :size="17"/></button></div>
        </div>
        <button class="studio-launch" @click="openOverlay('characters')"><UserRound :size="14"/> Character studio <span>ADRIAN / ALEX / CUSTOM</span></button>
        <button class="assignment-selector" @click="openOverlay('assignment')"><span>ASSIGNMENT TYPE</span><strong>{{TYPE_LABELS[nextAssignment]}}</strong><ChevronRight :size="16"/></button>
        <p class="mission-escalation">ROUND {{save.completed+1}} · {{save.completed?'INCREASING SURVEILLANCE':'FIRST ASSIGNMENT'}}</p><button class="primary start-button" @click="startMission" :disabled="loading || !!error"><span>{{ loading ? 'PREPARING ASSIGNMENT' : 'ENTER THE HOSPITAL' }}<small>MISSION {{ String(save.completed + 1).padStart(2, '0') }} / {{ save.settings.difficulty.toUpperCase() }}</small></span><ArrowRight :size="24"/></button>
        <div class="menu-links"><button @click="openOverlay('equipment')"><Crosshair :size="15"/> Equipment <span v-if="save.coins">{{ save.coins }}</span></button><button @click="openOverlay('controls')"><CircleHelp :size="15"/> How to play</button><button @click="openOverlay('settings')"><Settings2 :size="15"/> Settings</button></div>
        <p v-if="error" class="error-message">{{ error }}</p>
        </div>
      </section>
      <aside class="scene-label"><span class="eyebrow">NHALEWICK / MAIN BUILDING</span><span class="scene-title">The night shift.</span><p>Three public floors. A locked basement.<br/>More than one kind of assignment.</p><div class="scene-meta"><span>THREE CONNECTED WINGS</span><span>G + 1 + 2 + B</span></div></aside>
      <footer class="menu-footer"><span><Headphones :size="13"/> HEADPHONES RECOMMENDED</span><span class="menu-version">{{ ready ? 'READY TO ENTER' : 'LOADING CHARACTER ASSETS' }} <span class="live-dot" :class="{loading: !ready}"></span></span><button @click="openOverlay('credits')">BUILD 02.7.1 <ArrowUpRight :size="12"/></button></footer>
    </template>
    <StoryIntro v-if="screen==='story' && activeStory" :key="activeStory.id" :story="activeStory" :paused="!!overlay" @finish="enterHospital" @back="toMenu" @references="openOverlay('references')"/>
    <StoryIntro v-if="screen==='ending' && activeStory" :key="activeStory.id" :story="activeStory" :paused="!!overlay" ending @finish="showResults" @back="showResults"/>
    <template v-if="screen === 'game'">
      <header class="hud-top"><section class="mission-hud"><div class="eyebrow"><span class="live-dot" :class="{alert: hud.state==='escape'}"></span> {{ hud.state === 'escape' ? 'EMERGENCY / ESCAPE' : 'NHALEWICK / INFILTRATION' }}</div><div class="objective-row"><span class="objective-number">{{ objectiveNumber }}</span><div><span class="objective">{{ hud.objective }}</span><small>{{ hud.location }} <span> / </span> {{ FLOORS[hud.floor].toUpperCase() }}</small></div></div><div v-if="mission?.type==='standard'" class="evidence-progress"><i v-for="n in 3" :key="n" :class="{active: n <= hud.clues}"></i><span>{{ hud.clues }}/3 EVIDENCE FOUND</span></div></section>
        <section v-if="mission?.type==='standard'" class="target-hud"><div class="target-text"><span class="eyebrow">{{ hud.targetConfirmed ? 'IDENTITY CONFIRMED' : 'YOUR ASSIGNMENT' }}</span><strong>{{ mission?.target.name }}</strong><small>{{ (hud.clues && (!hud.covert?.documentRequired||hud.covert.documentTaken)) || hud.appointment ? `${mission?.target.room.name} · ${FLOORS[mission?.target.floor||0]}` : 'Department unknown' }}</small><small v-if="hud.appointment" class="appointment-detail">{{hud.appointment.complete?'Appointment complete':`Consultation · ${duration(hud.appointment.seconds)} left`}}<template v-if="hud.appointment.warningSeconds!==null"> · Leave warning in {{hud.appointment.warningSeconds}}s</template></small></div><div class="target-portrait" :class="{confirmed: hud.targetConfirmed}"><img :src="assignmentPortrait" alt="Assigned target portrait"/><span v-if="hud.state==='escape'"><Check :size="22"/></span><span v-else class="portrait-marker"><Target :size="14"/></span></div></section><section v-else class="special-assignment-hud"><span class="eyebrow">{{TYPE_LABELS[mission?.type]}}</span><strong>{{mission?.type==='evidence'?'Collect proof. No casualties.':'Bring the patient out alive.'}}</strong><small>KEYS {{hud.assignment?.keys.length||0}}/2 <span v-if="mission?.type==='evidence'"> · PHOTOS {{hud.assignment?.photos.length||0}}/3</span><span v-else-if="hud.assignment?.patientReleased"> · PATIENT {{hud.assignment.patientFloor===hud.floor?`${hud.assignment.patientDistance}m away`:'on another floor'}}</span></small></section>
      </header>
      <div v-if="hud.state === 'escape'" class="countdown" :class="{urgent: hud.timer < 30}"><Radio :size="15"/><span>{{mission?.type==='evidence'?'SECURITY SWEEP':'POLICE RESPONSE'}}</span><strong>{{ countdown }}</strong><small>Reach the main entrance · ground floor</small></div>
      <div v-if="hud.covert && !overlay && hud.state!=='escape' && (hud.covert.documentRequired || hud.covert.coffee!=='optional')" class="covert-status" role="status"><span v-if="hud.covert.documentRequired">ROTA: <b>{{hud.covert.documentTaken?'SECURED':hud.covert.breakState==='working'?'WAIT FOR COFFEE BREAK':hud.covert.breakState==='returning'?'DOCTOR RETURNING':hud.covert.window?`${hud.covert.window}s OPENING`:'DOCTOR LEAVING'}}</b></span><span v-if="hud.covert.coffee!=='optional'" class="coffee-hint">COFFEE: {{hud.covert.coffee.toUpperCase()}}</span></div>
      <div v-if="hud.scoped" class="scope-overlay" aria-label="Rifle scope"><span>SCOPED RIFLE / 80 M</span></div>
      <div class="reticle" :class="{aiming: hud.aiming, scoped:hud.scoped, hit}"><span></span><i></i><b></b></div>
      <div v-if="toast && !overlay && !hud.reports?.length" class="toast" :class="toast.kind"><span class="toast-line"></span><span>{{ toast.text }}</span></div>
      <button v-if="hud.prompt && !overlay" type="button" class="interaction-prompt" @pointerdown.stop @pointerup.stop.prevent="activatePrompt" @click.stop.prevent="activatePrompt"><kbd v-if="!isTouch">E</kbd><span>{{ hud.prompt.text }}</span></button>
      <div v-if="hud.reports?.length && !overlay && hud.state!=='escape'" class="witness-alert" role="status"><Eye :size="17"/><div><strong>{{hud.reports[0].reason==='privacy'?'SECURITY CALLED':hud.reports[0].reason==='camera'?'CAMERA SEEN':'WEAPON SEEN'}}</strong><span>{{hud.reports[0].name}} is reporting · {{hud.reports[0].seconds}}s</span><small>{{hud.reports[0].reason==='privacy'?'Staff are reporting the intrusion.':mission?.type==='evidence'?'Stay out of security’s view.':'Keep your weapon hidden until the objective.'}}</small></div></div>
      <div v-if="mission?.type==='standard' && hud.state==='escape' && !overlay" class="evacuation-reward"><Coins :size="15"/><span>STAFF BONUS <b>+{{hud.bonus||0}}</b></span><small>{{hud.evacuated||0}} evacuated · escape to bank coins</small></div>
      <div v-if="hud.contact && !overlay" class="contact-status" :class="hud.contact.state"><UserRound :size="13"/><div><strong>{{hud.contact.name}}</strong><small>{{hud.contact.label}}</small></div></div>
      <div v-if="hud.masked" class="mask-status"><Shield :size="13"/> MASK ON</div>
      <div v-if="hud.impairment > 0" class="status-effect"><Wind :size="15"/> CONTAMINATION <span>RECOVERY {{Math.ceil(hud.impairment)}}s</span></div>
      <div v-if="hud.blackout > 0" class="power-status"><Power :size="13"/> EMERGENCY POWER <small>{{ Math.ceil(hud.blackout) }}s</small></div>
      <div v-if="!overlay" class="npc-dialogues"><div v-for="(line,i) in hud.dialogues" :key="i" class="npc-dialogue" :style="{left: `${line.x}%`, top: `${line.y}%`}"><span>{{line.speaker}}</span><p>{{line.text}}</p></div></div>
      <div v-if="soundCaption && !overlay" class="ambient-caption">{{soundCaption}}</div>
      <div v-if="announcement && !overlay" class="announcement"><span><Radio :size="14"/> {{ announcement.label }}</span><p>“{{ announcement.text }}”</p></div>
      <footer class="hud-bottom"><section class="player-status"><div class="operative-name"><span class="status-bar"></span>{{ character.toUpperCase() }}<span class="eyebrow">{{ hud.crouched ? 'CROUCHED' : hud.suspicion > 70 ? 'EXPOSED' : hud.suspicion > 30 ? 'SUSPICIOUS' : 'UNNOTICED' }}</span></div><div class="stamina-track"><i :style="{width: `${hud.stamina}%`}"></i></div><div class="hud-tools"><button @click="engine.toggleFlash()" :class="{active: hud.flashlight}" title="Toggle flashlight (F)"><Flashlight :size="16"/><kbd v-if="!isTouch">F</kbd></button><button @click="openOverlay('journal')" title="Evidence journal (J)"><BookOpen :size="16"/><kbd v-if="!isTouch">J</kbd></button><button @click="pause" title="Pause game (Escape)"><Pause :size="15"/><kbd v-if="!isTouch">ESC</kbd></button><button @click="toggleSound" title="Toggle sound"><Volume2 v-if="save.settings.volume" :size="16"/><VolumeX v-else :size="16"/></button></div></section>
        <section class="weapon-status"><span class="weapon-label">{{ hud.reloading ? 'RELOADING' : (hud.weaponName||'SERVICE PISTOL') }}</span><div><strong>{{mission?.type==='evidence'?hud.assignment?.photos.length||0:String(hud.ammo).padStart(2,'0')}}</strong><span>/ {{mission?.type==='evidence'?'3 PHOTOS':String(hud.reserve).padStart(2,'0')}}</span><button v-if="mission?.type!=='evidence'" @click="engine.reload()" title="Reload (R)"><RotateCcw :size="14"/><kbd v-if="!isTouch">R</kbd></button></div><small>{{mission?.type==='evidence'?(isTouch?'Center the subject, then tap PHOTO':'Aim the camera · click or Space to photograph'):isTouch?'Tap AIM, then FIRE':'Hold right mouse to aim · left mouse to fire'}}</small></section>
        <button class="minimap" @click="openOverlay('map')" aria-label="Open hospital map"><MapView :floor="hud.floor" :hud="hud" :target="mission?.target" :clues="hud.clues" :assignment="hud.assignment" mini/><span><Map :size="13"/> {{FLOORS[hud.floor].toUpperCase()}} <kbd v-if="!isTouch">M</kbd></span></button>
      </footer>
      <div v-if="!isTouch && !locked && !overlay" class="mouse-hint">Click the scene for mouse look <span>·</span> arrow keys also turn</div>
      <div v-if="!isTouch && !overlay" class="desktop-gear"><button @click="engine.toggleWeapon()"><Crosshair :size="15"/> {{mission?.type==='evidence'?'CAMERA':hud.weaponDrawn?'HOLSTER':'DRAW'}} <kbd>G</kbd></button><button v-if="mission?.type!=='evidence' && save.upgrades.sniper" @click="engine.switchWeapon()">{{hud.weaponKind==='sniper'?'PISTOL':'RIFLE'}} <kbd>Q</kbd></button><button v-if="save.upgrades.mask" @click="engine.toggleMask()"><Shield :size="14"/> {{hud.masked?'REMOVE MASK':'MASK ON'}} <kbd>B</kbd></button></div>
      <TouchControls v-if="isTouch && !overlay && !loading" :engine="engine" :hud="hud" @map="openOverlay('map')" @journal="openOverlay('journal')" @pause="pause"/>
    </template>
    <section v-if="screen==='results' && result" class="results-screen"><div class="results-panel"><div class="eyebrow"><span class="line"></span> ASSIGNMENT {{ String(mission?.round).padStart(2,'0') }} / DEBRIEF</div><h2>{{ result.success ? 'OUT OF' : 'END OF' }}<br/><span>{{ result.success ? 'THE BUILDING.' : 'THE LINE.' }}</span></h2><p class="result-reason">{{ result.reason }}</p><div class="result-checks"><span :class="{yes: result.type==='standard'?result.targetDown:result.success}"><Check v-if="result.type==='standard'?result.targetDown:result.success" :size="15"/><X v-else :size="15"/> {{result.type==='evidence'?`${result.photos}/3 PHOTOS`:result.type==='rescue'?(result.rescued?'PATIENT RESCUED':'RESCUE INCOMPLETE'):result.targetDown?'TARGET ELIMINATED':'TARGET ACTIVE'}}</span><span :class="{yes: result.escaped}"><DoorOpen :size="15"/> {{ result.escaped ? 'ESCAPED' : 'INTERCEPTED' }}</span><span><Clock :size="15"/> {{ duration(result.duration) }}</span></div><div class="reward-card"><div><span class="eyebrow">MISSION REWARD</span><strong><Coins :size="25"/> {{ result.coins }}<small>COINS</small></strong></div><span class="balance">BALANCE <b>{{ save.coins }}</b></span></div><div v-if="result.breakdown.length" class="reward-breakdown"><div v-for="row in result.breakdown" :key="row.label"><span>{{ row.label }}</span><b>+{{ row.coins }}</b></div></div><p v-else class="failure-reward">Rewards are earned only after a successful escape.</p><button class="primary" @click="startMission"><span>{{ result.success ? 'NEXT ASSIGNMENT' : 'RETRY ASSIGNMENT' }}</span><ArrowRight :size="22"/></button><div class="result-actions"><button @click="openOverlay('equipment')"><Crosshair :size="16"/> Upgrade equipment</button><button @click="toMenu">Return to menu</button></div></div></section>
    <div v-if="loading" class="loading-screen"><div class="loader-mark"><Plus :size="42"/></div><span class="eyebrow">NHALEWICK MEDICAL CENTER</span><h3>Preparing your assignment.</h3><p>Loading the hospital and character assets…</p></div>
    <div v-if="overlay" class="modal-backdrop" @click.self="closeOverlay">
      <section class="modal" :class="{wide: ['map','equipment','controls','characters','references'].includes(overlay),'map-modal':overlay==='map'}" role="dialog" aria-modal="true" :aria-label="overlay">
        <header class="modal-header"><span class="eyebrow">NHALEWICK / {{ overlay === 'clue' ? 'EVIDENCE' : overlay.toUpperCase() }}</span><button class="icon-button" @click="closeOverlay" aria-label="Close dialog"><X :size="20"/></button></header>
        <template v-if="overlay==='contact' && contactDialog"><div class="eyebrow">UNEXPECTED CONTACT / {{contactDialog.stage==='offer'?'IN PRIVATE':'GROUND FLOOR'}}</div><h2>{{contactDialog.name}}</h2><p class="modal-lead">{{contactDialog.stage==='accepted'?'Your contact will act independently when the alarm begins.':contactDialog.stage==='offer'?'A risky offer. The primary target must still be eliminated first.':'A distressed visitor is pacing the atrium, trembling and asking for a quiet room.'}}</p><article class="contact-conversation"><span>{{contactLines[contactDialog.index]?.speaker}}</span><p>“{{contactLines[contactDialog.index]?.text}}”</p></article><button v-if="contactDialog.index<contactLines.length-1" class="primary" @click="nextContactLine">CONTINUE <ArrowRight :size="18"/></button><div v-else-if="contactDialog.stage==='invite'" class="contact-choices"><button class="primary" @click="contactChoice('escort')">FIND A PRIVATE ROOM <ArrowRight :size="18"/></button><button class="secondary" @click="contactChoice('dismiss')">Leave them in peace</button></div><div v-else-if="contactDialog.stage==='offer'" class="contact-choices"><button class="primary" @click="contactChoice('recruit')">MAKE THE OFFER <ArrowRight :size="18"/></button><button class="secondary" @click="contactChoice('dismiss')">Go alone</button></div><button v-else class="primary" @click="closeOverlay">RETURN TO THE ASSIGNMENT <ArrowRight :size="18"/></button></template>
        <template v-if="overlay==='assignment'"><h2>Choose the assignment.</h2><p class="modal-lead">{{screen==='game'?'Choosing a mission ends this attempt without a reward and starts the selected assignment. Your coins and upgrades stay saved.':'Special assignments also rotate into the campaign automatically. Choose one for your next round.'}}</p><div class="assignment-choices"><button v-for="type in ASSIGNMENT_TYPES" :key="type" @click="chooseAssignment(type)" :class="{selected:nextAssignment===type}"><strong>{{TYPE_LABELS[type]}}</strong><span>{{type==='standard'?'Investigate, confirm the assigned doctor, then escape.':type==='rescue'?'Find keys, stop the basement operation, and escort a patient out.':'Find keys, take three evidence photographs, and escape without killing.'}}</span><Check v-if="nextAssignment===type" :size="17"/></button></div></template>
        <template v-if="overlay==='pause'"><h2>Take a breath.</h2><p class="modal-lead">The hospital can wait. Your mission is paused.</p><div class="pause-actions"><button class="primary" @click="closeOverlay"><span>RESUME MISSION</span><ArrowRight :size="20"/></button><button class="secondary" @click="restartMission">Restart mission</button><button class="secondary" @click="overlay='assignment'">Choose a different mission</button><button class="secondary" @click="overlay='controls'">Controls & field guide</button><button class="secondary" @click="overlay='settings'">Settings</button><button class="text-button" @click="overlay='leave'">Abandon assignment</button></div></template>
        <template v-if="overlay==='leave'"><h2>Leave the assignment?</h2><p class="modal-lead">This mission will be recorded as unsuccessful. Your earned coins and upgrades stay saved.</p><button class="primary" @click="mission.finish(false, 'Assignment abandoned.'); persist(); toMenu()">ABANDON MISSION</button><button class="secondary" @click="closeOverlay">Keep playing</button></template>
        <template v-if="overlay==='characters'"><CharacterStudio :save="save" :engine="engine" @change="persist"/><button class="primary" @click="closeOverlay">SAVE LOOK <Check :size="18"/></button></template>
        <template v-if="overlay==='lift'"><h2>Choose your floor.</h2><p class="modal-lead">Nhalewick Medical Center / public floors and restricted basement</p><div class="lift-floors"><button v-for="(floor,i) in FLOORS" :key="floor" :disabled="hud.floor===i || i===3 && (mission?.type==='standard' || !hud.assignment?.keys.includes('basement'))" @click="useLift(i)"><b>{{FLOOR_CODES[i]}}</b><span>{{floor}}<small>{{i===3&&!hud.assignment?.keys.includes('basement')?'LOCKED · access pass required':FLOOR_THEMES[i]}}</small></span><Check v-if="hud.floor===i" :size="18"/><ArrowRight v-else :size="18"/></button></div></template>
        <template v-if="overlay==='references'"><h2>Behind the case files.</h2><p class="modal-lead">{{STORY_NOTICE}}</p><div class="story-references"><article v-for="source in STORY_SOURCES" :key="source.id"><span class="eyebrow">{{source.publisher}}</span><a :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title}} <ArrowUpRight :size="13"/></a><p>{{source.note}}</p></article></div></template>
        <template v-if="overlay==='map'"><div class="modal-title-row"><h2>Know your way out.</h2><div class="floor-tabs"><button v-for="(floor,i) in FLOORS" :key="floor" :class="{selected:mapFloor===i}" @click="mapFloor=i">{{FLOOR_CODES[i]}}</button></div></div><div class="map-layout"><MapView :floor="mapFloor" :hud="hud" :target="mission?.target" :clues="hud.clues" :assignment="hud.assignment"/><aside class="map-notes"><span class="eyebrow">{{FLOORS[mapFloor].toUpperCase()}}</span><h3>{{FLOOR_THEMES[mapFloor]}}</h3><div class="map-legend"><span><i class="blue-dot"></i> Your position</span><span><i class="gold-dot"></i> Evidence terminals</span><span><i class="outline-dot"></i> Known departments</span><span>✚ Antidote cabinets · floors 1 &amp; 2</span><span v-if="mission?.type!=='standard'">K · keys / C · camera subjects</span></div><p>Doors connect the concourse and outer passages. Use either route to move between wings.</p><p>The north lift connects the three public floors. The basement requires an access pass from Records during a special assignment. The main entrance is on the ground floor.</p><p>Contaminated? Each upper floor has a green antidote cabinet in the north concourse beside the lift. Use it to restore clear vision. Each cabinet holds one dose per assignment.</p><div v-if="hud.clues" class="known-location"><span class="eyebrow">CONFIRMED ASSIGNMENT</span><strong>{{ mission?.target.room.name }}</strong><small>{{ mission?.target.room.wing }} wing · {{FLOORS[mission?.target.floor||0]}}</small></div><button class="secondary" @click="closeOverlay">RETURN TO MISSION <kbd v-if="!isTouch">M</kbd></button></aside></div></template>
        <template v-if="overlay==='journal'"><div v-if="mission?.type!=='standard'" class="special-journal"><h3>{{TYPE_LABELS[mission?.type]}}</h3><p>Basement access pass: Records, ground floor. Theatre key: spare in Maintenance, or crouch behind the passing charge nurse and use TALK/USE without being seen.</p><p v-if="mission?.type==='evidence'">Photograph the ledger in Records (G), the consent file in Research (2), and the operating theatre (B). Center each subject in the camera from nearby and take a photo. Keep clear of security.</p><p v-else>Stop both operating doctors, release the patient beside the bed, then stay close as they follow you to the lift and main entrance. Other staff are protected.</p><div v-if="mission?.photos.length" class="evidence-photos"><figure v-for="id in mission.photos" :key="id"><img v-if="mission.photoImages?.[id]" :src="mission.photoImages[id]" :alt="`Evidence photo: ${id}`"/><figcaption>{{id}}</figcaption></figure></div></div><template v-if="mission?.type==='standard'"><h2>Follow the evidence.</h2><p v-if="hud.appointment" class="modal-lead">{{hud.appointment.complete?'The consultation has ended. The doctor is available.':`Consultation in ${hud.appointment.room}: ${duration(hud.appointment.seconds)} remaining. You have 30 seconds after the first request before the leave warning. Wait outside for the patient to finish.`}}</p><p class="modal-lead">{{ mission?.target.name }} / {{ hud.clues }} of 3 records found</p><div v-if="mission?.clues.length" class="journal"><article v-for="(item,i) in mission.clues" :key="item.type"><span class="section-number">0{{i+1}}</span><div><span class="eyebrow">{{item.source}}</span><h3>{{item.title}}</h3><p>{{item.text}}</p><small>RECORDED {{duration(item.time)}}</small></div></article></div><div v-else class="empty-journal"><BookOpen :size="32"/><p>No evidence yet. Inspect the staff directory in the entrance atrium, staff schedules in the east concourse, or the handover logs outside the clinical wings.</p></div></template><button class="secondary" @click="closeOverlay">CONTINUE INVESTIGATION <kbd v-if="!isTouch">J</kbd></button></template>
        <template v-if="overlay==='clue' && clue"><div class="clue-icon"><BookOpen :size="27"/></div><h2>{{clue.title}}.</h2><span class="eyebrow">{{clue.source}}</span><p class="clue-text">{{clue.text}}</p><div class="record-state"><Check :size="15"/> ADDED TO EVIDENCE JOURNAL</div><button class="primary" @click="closeOverlay"><span>RECORD & CONTINUE</span><ArrowRight :size="20"/></button></template>
        <template v-if="overlay==='badge' && badge"><div class="clue-icon"><UserRound :size="27"/></div><span class="eyebrow">STAFF IDENTITY / VERIFIED</span><h2>{{badge.name}}</h2><p class="modal-lead">{{badge.role}}</p><div class="badge-match" :class="{matched: badge.target}"><Target :size="18"/> {{ badge.target ? 'MATCHES YOUR ASSIGNMENT' : 'DOES NOT MATCH YOUR ASSIGNMENT' }}</div><p>{{badge.target ? 'Identity confirmed. Complete the objective, then reach the main entrance before police respond.' : 'Continue your investigation. Verify the name on the badge before you act.'}}</p><button class="primary" @click="closeOverlay">CONTINUE <ArrowRight :size="20"/></button></template>
        <template v-if="overlay==='equipment'"><div class="modal-title-row"><div><h2>Travel light.</h2><p class="modal-lead">Equipment upgrades persist across assignments.</p></div><div class="equipment-balance"><Coins :size="18"/> {{save.coins}}</div></div><div class="expanded-loadout"><div><span class="eyebrow">EQUIPPED WEAPON</span><div class="loadout-choice"><button :class="{selected:save.loadout.weapon==='pistol'}" @click="save.loadout.weapon='pistol';loadoutChanged()">Pistol <small>{{weaponInfo(save,'pistol').capacity}} rounds / 28 m</small></button><button :disabled="!save.upgrades.sniper" :class="{selected:save.loadout.weapon==='sniper'}" @click="save.loadout.weapon='sniper';loadoutChanged()">Scoped rifle <small>{{save.upgrades.sniper?`${weaponInfo(save,'sniper').capacity} rounds / 80 m`:'Unlock below'}}</small></button></div></div><div class="loadout-accessories"><button :disabled="!save.upgrades.mask" :class="{selected:save.loadout.mask}" @click="save.loadout.mask=!save.loadout.mask;loadoutChanged()"><Shield :size="17"/> Mask {{save.loadout.mask?'ON':'OFF'}}<small>{{save.upgrades.mask?'Blocks new gas exposure':'Purchase below'}}</small></button><button :class="{selected:save.appearance.jewelry}" @click="save.appearance.jewelry=!save.appearance.jewelry;loadoutChanged()">Steel jewelry {{save.appearance.jewelry?'ON':'OFF'}}<small>Remove before MRI</small></button></div></div><div class="upgrade-grid"><article v-for="(u,i) in UPGRADE_INFO" :key="u.id"><component :is="[Footprints,Flashlight,Wind,Crosshair,Shield,Target,RotateCcw,HeartPulse][i]" :size="25"/><span class="eyebrow">LEVEL {{save.upgrades[u.id]}} / {{u.max}}</span><h3>{{u.name}}</h3><p>{{u.description}}</p><button @click="buy(u.id)" :disabled="save.upgrades[u.id]>=u.max || save.coins<u.cost*(save.upgrades[u.id]+1)"><template v-if="save.upgrades[u.id]>=u.max"><Check :size="15"/> FULLY UPGRADED</template><template v-else>UPGRADE <span><Coins :size="14"/> {{u.cost*(save.upgrades[u.id]+1)}}</span></template></button></article></div><p class="equipment-tip">Eliminate the primary target first. Additional staff earn 25 coins each during evacuation. Patients remain protected. Escape to bank rewards; buy masks, weapons and training. Create your own look in the character studio.</p></template>
        <template v-if="overlay==='settings'"><h2>Make yourself comfortable.</h2><div class="settings-list"><label><span>Sound volume<small>Music, atmosphere & effects</small></span><input type="range" min="0" max="1" step=".05" v-model.number="save.settings.volume" @input="settingsChanged"/></label><label><span>Spoken dialogue & announcements<small>Captions are always shown</small></span><input type="checkbox" v-model="save.settings.speech" @change="settingsChanged"/></label><label><span>{{isTouch?'Camera sensitivity':'Mouse sensitivity'}}</span><input type="range" min=".3" max="2" step=".1" v-model.number="save.settings.sensitivity" @input="settingsChanged"/></label><label><span>Scene brightness<small>Brighten the hospital view</small></span><input aria-label="Scene brightness" type="range" min=".75" max="1.75" step=".05" v-model.number="save.settings.brightness" @input="settingsChanged"/></label><label><span>Torch brightness<small>Adjust the flashlight beam</small></span><input aria-label="Torch brightness" type="range" min=".5" max="2.5" step=".1" v-model.number="save.settings.flashlightBrightness" @input="settingsChanged"/></label><label><span>Visual quality<small>Balanced helps slower devices</small></span><select v-model="save.settings.quality" @change="settingsChanged"><option value="high">High</option><option value="balanced">Balanced</option><option value="low">Low</option></select></label><label><span>Mission difficulty<small>Applies to your next assignment</small></span><select v-model="save.settings.difficulty" @change="settingsChanged"><option value="relaxed">Relaxed · 150s escape</option><option value="standard">Standard · 110s escape</option><option value="hard">Hard · 75s escape</option></select></label></div><button v-if="!native" class="secondary" @click="fullscreen"><Maximize :size="16"/> Toggle fullscreen</button><p class="settings-note">Your settings, coins, and equipment save automatically in this browser.</p></template>
        <template v-if="overlay==='controls'"><h2>Your night-shift field guide.</h2><p class="modal-lead">Later assignments restrict exact staff allocations. Watch the Records custodian leave for coffee, then collect the paper rota unseen. From round four, cross-check the wing handover log before confirming a badge.</p><p class="modal-lead">An alternative target route: collect the fictional KTD compound in Pharmacy, verify the target, and tamper with their personal coffee beside the lift on their floor while nobody is watching. The doctor takes a break after finishing any consultation. Being seen taking the rota or tampering with coffee ends the assignment.</p><div class="controls-layout"><section v-if="isTouch" class="controls-list"><div><span>Move / strafe</span><b>Left thumbstick</b></div><div><span>Look around</span><b>Drag right side</b></div><div><span>Zoom camera</span><b>Pinch the scene with two fingers</b></div><div><span>Sprint / crouch</span><b>RUN / CROUCH</b></div><div><span>Doors, badges, clues, lift</span><b>USE</b></div><div><span>Draw / holster</span><b>DRAW / HIDE</b></div><div><span>Switch weapon / mask</span><b>RIFLE / MASK</b></div><div><span>Flashlight</span><b>LIGHT</b></div><div><span>Aim / shoot</span><b>AIM / FIRE</b></div><div><span>Adjust aim while firing</span><b>Drag FIRE</b></div><div><span>Reload</span><b>RELOAD</b></div><div><span>Map / journal / pause</span><b>Top-right icons</b></div></section><section v-else class="controls-list"><div><span>Move / strafe</span><b><kbd v-if="!isTouch">W</kbd><kbd v-if="!isTouch">A</kbd><kbd v-if="!isTouch">S</kbd><kbd v-if="!isTouch">D</kbd></b></div><div><span>Look around</span><b>Mouse / <kbd v-if="!isTouch">←</kbd><kbd v-if="!isTouch">→</kbd></b></div><div><span>Run / crouch</span><b><kbd v-if="!isTouch">SHIFT</kbd><kbd v-if="!isTouch">C</kbd></b></div><div><span>Read / inspect / use door</span><kbd v-if="!isTouch">E</kbd></div><div><span>Flashlight</span><kbd v-if="!isTouch">F</kbd></div><div><span>Aim / fire</span><b>Right / left mouse</b></div><div><span>Keyboard aim / fire</span><b><kbd v-if="!isTouch">V</kbd><kbd v-if="!isTouch">SPACE</kbd></b></div><div><span>Reload</span><kbd v-if="!isTouch">R</kbd></div><div><span>Draw / holster</span><kbd>G</kbd></div><div><span>Switch weapon / mask</span><b><kbd>Q</kbd><kbd>B</kbd></b></div><div><span>Map / evidence / pause</span><b><kbd v-if="!isTouch">M</kbd><kbd v-if="!isTouch">J</kbd><kbd v-if="!isTouch">ESC</kbd></b></div></section><section class="field-guide"><article><span>01</span><div><h3>Investigate.</h3><p>Read the directory in the atrium. Schedules and handover logs reveal the department and room. Use the map to plan your route.</p></div></article><article><span>02</span><div><h3>Confirm the badge.</h3><p>Approach staff and {{ isTouch ? 'tap USE' : 'press E' }}. Keep your gun holstered until you are ready. Witnesses gasp and run to report visible weapons. Only the assigned doctor may be harmed before the primary objective. Patients are always protected.</p></div></article><article><span>03</span><div><h3>Find your exit.</h3><p>The primary target triggers an immediate alarm and evacuation. Additional staff are worth 25 coins each, but you must reach the ground-floor exit to bank rewards. Buy a mask to block gas, or find an antidote cabinet on floor 1 or 2 to cure contamination. Remove steel jewelry before MRI.</p></div></article><article><span>04</span><div><h3>An unexpected contact.</h3><p>On three assignments in every ten, a distressed visitor may arrive later in the assignment, alternating panicked runs with sudden quiet spells. Talk to them, lead them into an empty ground-floor bathroom, and talk again. An accepted contact waits for the primary target, then acts independently.</p></div></article><article><span>05</span><div><h3>Special assignments.</h3><p>Choose Rescue or Evidence from the home screen or pause menu. Collect a basement pass in Records and a theatre key in Maintenance, or quietly lift it from the charge nurse while crouched behind her. Rescue requires stopping both operating doctors and escorting the patient out. Evidence only uses CAMERA and PHOTO in place of weapon controls; collect all three images without killing anyone.</p></div></article></section></div><p class="controls-note">{{isTouch?'Use the movement stick and drag the right side to look. Pinch the scene to zoom. USE interacts, AIM steadies your weapon, and FIRE shoots. Maps and menus pause the mission.':'Click the scene to capture the mouse. Escape releases it. Maps and menus pause the mission.'}}</p><button class="primary" @click="closeOverlay">UNDERSTOOD <Check :size="18"/></button></template>
        <template v-if="overlay==='credits'"><h2>Nhalewick after hours.</h2><p class="modal-lead">KTD · Kill the Doctor · Playable browser edition</p><p>Built with Vue 3, Three.js, and Web Audio. Original modular hospital, procedural medical equipment, dynamic lighting, character rigs, and persistent mission progression.</p><p>Avatar assets from Ready Player Me / Wolf3D through the three.ws sample collection. Animation clips from Adobe Mixamo.</p><p>All people, events, and medical effects in this game are fictional.</p><p><a :href="assetUrl('credits.txt')" target="_blank" rel="noopener">Asset sources & license notices ↗</a></p><p>Human cough: OwlStorm / Owlish Media, CC0. Recorded laughter: jodybruchon and Kalibrk / Freesound (CC0), with source records included in the audio assets. “gasp01.wav” by <a href="https://freesound.org/people/FreqMan/sounds/31356/" target="_blank" rel="noopener">FreqMan / Freesound</a>, licensed <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Sneaker footsteps by SpliceSound and weapon recordings by michorvath and moosegravy via Freesound (CC0); source records are included with the assets. Original story illustrations generated with ImageGen. NPC dialogue and announcements use Qwen3-TTS synthetic voices designed for this game, with standard American and Southern-inspired delivery. No real person’s voice was cloned. Generation models are Apache 2.0 licensed; full source and license notices are included with the audio.</p><button class="secondary" @click="overlay='references'">Story references <BookOpen :size="15"/></button><span class="eyebrow">LOCAL SAVE / NO ACCOUNT REQUIRED</span></template>
      </section>
    </div>
  </main>
</template>
